using System;using System.IO;using System.Reflection;using System.Collections.Generic;using UnityEngine;using UnityEngine.EventSystems;using Bokumyaku.Presentation;using Bokumyaku.Simulation;
public static class RepairHudCheck{
 public static object Run(){var g=UnityEngine.Object.FindFirstObjectByType<BokumyakuGame>();if(!g.SavePath.Contains("ink-qa-"))throw new Exception("Isolated only");var hud=UnityEngine.Object.FindFirstObjectByType<BokumyakuBattleHud>();var refresh=typeof(BokumyakuBattleHud).GetMethod("Refresh",BindingFlags.Instance|BindingFlags.NonPublic);var hp=typeof(RunSimulator).GetProperty("CoreHp");var ink=typeof(RunSimulator).GetProperty("RunInk");var count=typeof(RunSimulator).GetField("repairCount",BindingFlags.Instance|BindingFlags.NonPublic);var rows=new List<object>();hp.SetValue(g.Run,6);ink.SetValue(g.Run,1000);refresh.Invoke(hud,null);Canvas.ForceUpdateCanvases();int cost=g.Run.RepairCost;Click();rows.Add(new{name="repair purchase",passed=g.Run.CoreHp==8&&g.Run.RunInk==1000-cost&&g.Run.RepairCount==1});hp.SetValue(g.Run,10);refresh.Invoke(hud,null);int balance=g.Run.RunInk;Click();rows.Add(new{name="full hp rejected",passed=g.Run.RunInk==balance&&g.Run.RepairCount==1});hp.SetValue(g.Run,6);ink.SetValue(g.Run,0);refresh.Invoke(hud,null);Click();rows.Add(new{name="insufficient ink rejected",passed=g.Run.CoreHp==6&&g.Run.RepairCount==1});ink.SetValue(g.Run,1000);count.SetValue(g.Run,5);refresh.Invoke(hud,null);Click();rows.Add(new{name="cap rejected",passed=g.Run.CoreHp==6&&g.Run.RunInk==1000&&g.Run.RepairCount==5});File.WriteAllText(Path.GetFullPath("../docs/evidence/repair-hud-check.json"),Newtonsoft.Json.JsonConvert.SerializeObject(rows,Newtonsoft.Json.Formatting.Indented));ScreenCapture.CaptureScreenshot(Path.GetFullPath("../docs/evidence/repair-hud.png"));return rows;}
 static void Click(){var b=GameObject.Find("Repair").GetComponent<UnityEngine.UI.Button>();var r=(RectTransform)b.transform;var d=new PointerEventData(EventSystem.current){position=RectTransformUtility.WorldToScreenPoint(null,r.TransformPoint(r.rect.center)),button=PointerEventData.InputButton.Left};var hits=new List<RaycastResult>();EventSystem.current.RaycastAll(d,hits);if(hits.Count==0||hits[0].gameObject.GetComponentInParent<UnityEngine.UI.Button>()!=b)throw new Exception("Blocked repair");ExecuteEvents.Execute(b.gameObject,d,ExecuteEvents.pointerClickHandler);}}
